-- Independent local programme purposes, worker-only real media receipts and controls.
CREATE TABLE _dg_native_programme_consents(grant_id text PRIMARY KEY REFERENCES live_guest_programme_grants(id),payload text NOT NULL,consent_hash text NOT NULL CHECK(consent_hash=encode(sha256(convert_to(payload,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TABLE _dg_native_programme_instructions(connection_id text NOT NULL REFERENCES live_guest_programme_connections(id),version bigint NOT NULL,generation_id text NOT NULL REFERENCES live_output_generations(id),runtime_token text NOT NULL,payload text NOT NULL,payload_hash text NOT NULL CHECK(payload_hash=encode(sha256(convert_to(payload,'UTF8')),'hex')),created_at text NOT NULL,PRIMARY KEY(connection_id,version));
CREATE FUNCTION dg_native_programme_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$ BEGIN RAISE EXCEPTION 'Native programme input and selected frame instructions are immutable';END $dg$;
CREATE TRIGGER native_programme_consent_immutable BEFORE UPDATE OR DELETE ON _dg_native_programme_consents FOR EACH ROW EXECUTE FUNCTION dg_native_programme_append_only();
CREATE TRIGGER native_programme_instruction_immutable BEFORE UPDATE OR DELETE ON _dg_native_programme_instructions FOR EACH ROW EXECUTE FUNCTION dg_native_programme_append_only();
ALTER TABLE live_guest_programme_grants ADD CONSTRAINT native_programme_grant_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND version>0 AND available_camera IN(0,1) AND available_microphone IN(0,1) AND available_camera+available_microphone>0 AND camera IN(0,1) AND microphone IN(0,1) AND camera<=available_camera AND microphone<=available_microphone AND recording_required IN(0,1) AND recording_allowed IN(0,1) AND length(public_name)<=40 AND (consent_hash IS NULL OR consent_hash ~ '^[a-f0-9]{64}$') AND (cookie_hash IS NULL OR cookie_hash ~ '^[a-f0-9]{64}$'));
ALTER TABLE live_guest_programme_connections ADD CONSTRAINT native_programme_connection_shape CHECK(version>0 AND guest_sequence>=0 AND audio_muted IN(0,1) AND video_hidden IN(0,1) AND video_ready IN(0,1) AND audio_ready IN(0,1) AND rtp_audio BETWEEN 0 AND 1000000000000 AND rtp_video BETWEEN 0 AND 1000000000000 AND decoded_frames BETWEEN 0 AND 1000000000000 AND decoded_pcm_bytes BETWEEN 0 AND 1000000000000 AND ((server_offer IS NULL AND server_offer_hash IS NULL) OR octet_length(server_offer) BETWEEN 1 AND 65536 AND server_offer_hash=encode(sha256(convert_to(server_offer,'UTF8')),'hex')) AND ((guest_answer IS NULL AND guest_answer_hash IS NULL) OR octet_length(guest_answer) BETWEEN 1 AND 65536 AND guest_answer_hash=encode(sha256(convert_to(guest_answer,'UTF8')),'hex')));
ALTER TABLE live_guest_programme_controls ADD CONSTRAINT native_programme_control_shape CHECK(version>0 AND session_version>0 AND (status<>'applied' OR applied_at IS NOT NULL AND media_frame>=0));

CREATE FUNCTION dg_native_programme_payload(r live_guest_programme_grants) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT jsonb_build_object('id',r.id,'inviteId',r.invite_id,'peerAttemptId',r.peer_attempt_id,'guestId',r.guest_id,'sessionId',r.session_id,'outputId',r.output_id,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'actorId',r.actor_id,'availableCamera',r.available_camera,'availableMicrophone',r.available_microphone,'camera',r.camera,'microphone',r.microphone,'publicName',r.public_name,'clientId',r.client_id,'recordingRequired',r.recording_required,'recordingAllowed',r.recording_allowed,'expiresAt',r.expires_at,'statementVersion',r.statement_version,'consentedAt',r.consented_at,'environment',r.environment,'appEnv',r.app_env)
$dg$;
CREATE FUNCTION dg_native_programme_source_valid(p_grant text,p_connection text,p_tenant text,p_workspace text,p_recording boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT EXISTS(SELECT 1 FROM live_guest_programme_grants r JOIN live_guest_programme_connections c ON c.grant_id=r.id JOIN _dg_native_programme_consents x ON x.grant_id=r.id WHERE r.id=p_grant AND c.id=p_connection AND r.tenant_id=p_tenant AND r.workspace_id=p_workspace AND r.environment='mock' AND r.app_env IN('development','sandbox') AND r.status='consented' AND r.withdrawn_at IS NULL AND r.expires_at::timestamptz>clock_timestamp() AND x.consent_hash=r.consent_hash AND x.payload::jsonb=dg_native_programme_payload(r) AND (NOT p_recording OR r.recording_allowed=1) AND dg_native_peer_actor_valid(r.actor_id,r.tenant_id,r.workspace_id))
$dg$;
CREATE FUNCTION dg_native_programme_live_valid(p_grant text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT EXISTS(SELECT 1 FROM live_guest_programme_grants r JOIN live_peer_attempts a ON a.id=r.peer_attempt_id JOIN live_peer_invites i ON i.id=r.invite_id JOIN live_peer_guests g ON g.id=r.guest_id JOIN live_peer_consents c ON c.guest_id=g.id AND c.version=a.consent_version JOIN live_sessions s ON s.id=r.session_id JOIN live_outputs o ON o.id=r.output_id JOIN _dg_native_programme_consents x ON x.grant_id=r.id WHERE r.id=p_grant AND r.status='consented' AND r.withdrawn_at IS NULL AND r.expires_at::timestamptz>clock_timestamp() AND x.consent_hash=r.consent_hash AND x.payload::jsonb=dg_native_programme_payload(r) AND i.status='used' AND i.expires_at::timestamptz>clock_timestamp() AND i.session_id=s.id AND a.invite_id=i.id AND a.guest_id=g.id AND a.status='active' AND a.guest_client_id=r.client_id AND a.host_lease_until::timestamptz>clock_timestamp() AND a.guest_lease_until::timestamptz>clock_timestamp() AND g.status='approved' AND g.consent_version=a.consent_version AND g.client_id=r.client_id AND c.withdrawn_at IS NULL AND c.expires_at::timestamptz>clock_timestamp() AND s.status IN('live','preview') AND s.invalidated_at IS NULL AND o.status='running' AND o.invalidated_at IS NULL AND o.withdrawn_at IS NULL AND o.published_frames>0 AND o.session_id=s.id AND o.snapshot::jsonb->'settings'->'guestProgramme'->>'enabled'='true' AND dg_native_peer_actor_valid(r.actor_id,r.tenant_id,r.workspace_id) AND dg_native_peer_actor_valid(a.host_id,r.tenant_id,r.workspace_id) AND dg_native_peer_actor_valid(i.actor_id,r.tenant_id,r.workspace_id))
$dg$;
CREATE FUNCTION dg_native_programme_output_lease(p_output text,p_generation text,p_token text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT EXISTS(SELECT 1 FROM live_outputs o JOIN live_output_generations g ON g.id=o.generation_id WHERE o.id=p_output AND g.id=p_generation AND g.output_id=o.id AND o.lease_token=p_token AND g.lease_token=p_token AND o.lease_until::timestamptz>clock_timestamp() AND o.status IN('running','stopping') AND o.invalidated_at IS NULL AND o.withdrawn_at IS NULL AND o.snapshot::jsonb->'settings'->'guestProgramme'->>'enabled'='true' AND dg_native_peer_actor_valid(o.actor_id,o.tenant_id,o.workspace_id))
$dg$;

CREATE FUNCTION dg_native_programme_grant_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE i live_peer_invites%ROWTYPE;a live_peer_attempts%ROWTYPE;s live_sessions%ROWTYPE;o live_outputs%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('native-programme-output:'||NEW.output_id,0));SELECT * INTO STRICT i FROM live_peer_invites WHERE id=NEW.invite_id;SELECT * INTO STRICT a FROM live_peer_attempts WHERE id=NEW.peer_attempt_id;SELECT * INTO STRICT s FROM live_sessions WHERE id=NEW.session_id;SELECT * INTO STRICT o FROM live_outputs WHERE id=NEW.output_id;
  IF (NEW.tenant_id,NEW.workspace_id,NEW.environment,NEW.app_env,NEW.session_id) IS DISTINCT FROM (i.tenant_id,i.workspace_id,i.environment,i.app_env,i.session_id) OR NEW.output_id<>o.id OR o.session_id<>s.id OR a.invite_id<>i.id OR a.guest_id<>NEW.guest_id OR a.host_id<>NEW.actor_id OR a.status<>'active' OR i.status<>'used' OR s.status NOT IN('live','preview') OR o.status<>'running' OR o.published_frames<1 OR s.invalidated_at IS NOT NULL OR o.invalidated_at IS NOT NULL OR o.snapshot::jsonb->'settings'->'guestProgramme'->>'enabled' IS DISTINCT FROM 'true' OR NOT dg_native_peer_actor_valid(NEW.actor_id,NEW.tenant_id,NEW.workspace_id) OR NEW.status<>'requested' OR NEW.version<>1 OR NEW.camera+NEW.microphone+NEW.recording_allowed<>0 OR NEW.client_id IS NOT NULL OR NEW.consent_hash IS NOT NULL OR NEW.cookie_hash IS NOT NULL OR NEW.consented_at IS NOT NULL OR NEW.withdrawn_at IS NOT NULL OR NEW.expires_at<>i.expires_at OR NEW.recording_required<>(CASE WHEN s.kind<>'preview' AND s.snapshot::jsonb->'definition'->>'recordingEnabled'='true' THEN 1 ELSE 0 END) OR NEW.available_camera<>(SELECT camera FROM live_peer_consents WHERE guest_id=a.guest_id AND version=a.consent_version) OR NEW.available_microphone<>(SELECT microphone FROM live_peer_consents WHERE guest_id=a.guest_id AND version=a.consent_version) THEN RAISE EXCEPTION 'Native programme request must match active approved backstage media';END IF;
  IF NEW.public_name<>'' OR NEW.statement_version IS NOT NULL OR i.expires_at::timestamptz<=clock_timestamp() OR a.host_lease_until::timestamptz<=clock_timestamp() OR a.guest_lease_until::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION 'Native programme request requires current device leases';END IF;
  IF (SELECT count(*) FROM live_guest_programme_grants WHERE invite_id=i.id)>=10 OR (SELECT count(*) FROM live_guest_programme_grants WHERE output_id=o.id)>=100 OR EXISTS(SELECT 1 FROM live_guest_programme_grants r LEFT JOIN live_guest_programme_connections c ON c.grant_id=r.id WHERE r.invite_id=i.id AND (r.status='requested' OR r.status='consented' AND c.status IN('queued','connecting','connected'))) THEN RAISE EXCEPTION 'Native programme request capacity reached';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','version','recording_allowed','camera','microphone','public_name','client_id','statement_version','consent_hash','consented_at','cookie_hash','withdrawn_at','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','recording_allowed','camera','microphone','public_name','client_id','statement_version','consent_hash','consented_at','cookie_hash','withdrawn_at','updated_at']) OR OLD.status IN('rejected','withdrawn','expired') OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Native programme request identity and closure are immutable';END IF;
  IF NEW.status='consented' THEN
   IF OLD.status<>'requested' OR NEW.camera+NEW.microphone<1 OR NEW.client_id IS NULL OR NEW.public_name='' OR NEW.statement_version<>'local-programme-v1' OR NEW.consented_at IS NULL OR NEW.consent_hash IS NULL OR NEW.cookie_hash IS NULL OR NEW.recording_allowed<>NEW.recording_required OR NEW.expires_at::timestamptz<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM _dg_native_programme_consents x WHERE x.grant_id=NEW.id AND x.consent_hash=NEW.consent_hash AND x.payload::jsonb=dg_native_programme_payload(NEW)) THEN RAISE EXCEPTION 'Native programme consent requires its exact independent purpose receipt';END IF;
  ELSIF NEW.status IN('withdrawn','expired','rejected') THEN
   IF (to_jsonb(NEW)-ARRAY['status','version','cookie_hash','withdrawn_at','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','cookie_hash','withdrawn_at','updated_at']) THEN RAISE EXCEPTION 'Native programme closed consent cannot change';END IF;NEW.cookie_hash:=NULL;NEW.withdrawn_at:=coalesce(OLD.withdrawn_at,NEW.withdrawn_at,dg_utc_now());
  ELSE RAISE EXCEPTION 'Native programme state transition is invalid';END IF;
 END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_programme_grant_guard BEFORE INSERT OR UPDATE ON live_guest_programme_grants FOR EACH ROW EXECUTE FUNCTION dg_native_programme_grant_guard();
CREATE FUNCTION dg_native_programme_pair_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_guest_programme_grants%ROWTYPE;grant_ref text;x _dg_native_programme_consents%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='live_guest_programme_grants' THEN grant_ref:=NEW.id;ELSE grant_ref:=NEW.grant_id;END IF;SELECT * INTO STRICT r FROM live_guest_programme_grants WHERE id=grant_ref;SELECT * INTO x FROM _dg_native_programme_consents WHERE grant_id=r.id;
 IF r.status='consented' AND (x.grant_id IS NULL OR NOT EXISTS(SELECT 1 FROM live_guest_programme_connections c WHERE c.grant_id=r.id AND c.peer_attempt_id=r.peer_attempt_id AND c.output_id=r.output_id)) OR x.grant_id IS NOT NULL AND (r.consent_hash IS DISTINCT FROM x.consent_hash OR x.payload::jsonb IS DISTINCT FROM dg_native_programme_payload(r)) THEN RAISE EXCEPTION 'Native programme consent and connection must commit together';END IF;RETURN NEW;
END $dg$;
CREATE CONSTRAINT TRIGGER native_programme_grant_pair AFTER INSERT OR UPDATE ON live_guest_programme_grants DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_programme_pair_guard();
CREATE CONSTRAINT TRIGGER native_programme_consent_pair AFTER INSERT ON _dg_native_programme_consents DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_programme_pair_guard();

-- The native lifecycle owns closure; keep the baseline immutable-input guards.
DROP TRIGGER live_guest_programme_grant_cleanup ON live_guest_programme_grants;
DROP TRIGGER live_guest_programme_peer_end ON live_peer_attempts;
DROP TRIGGER live_guest_programme_invite_close ON live_peer_invites;
DROP TRIGGER live_guest_programme_generation_change ON live_outputs;
DROP TRIGGER live_guest_programme_mix_change ON live_guest_programme_connections;
CREATE FUNCTION dg_native_programme_connection_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_guest_programme_grants%ROWTYPE;worker_name text;
BEGIN
 SELECT * INTO STRICT r FROM live_guest_programme_grants WHERE id=NEW.grant_id;SELECT worker_role INTO worker_name FROM _dg_native_runtime_control WHERE id=1;
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('native-programme-output:'||NEW.output_id,0));
  IF NEW.output_id<>r.output_id OR NEW.peer_attempt_id<>r.peer_attempt_id OR NOT dg_native_programme_live_valid(r.id) OR NEW.status<>'queued' OR NEW.version<>1 OR NEW.mix_state<>'preview' OR NEW.audio_muted<>0 OR NEW.video_hidden<>0 OR NEW.guest_sequence<>0 OR NEW.generation_id IS NOT NULL OR NEW.runtime_token IS NOT NULL OR NEW.server_offer IS NOT NULL OR NEW.guest_answer IS NOT NULL OR NEW.rtp_audio+NEW.rtp_video+NEW.decoded_frames+NEW.decoded_pcm_bytes+NEW.video_ready+NEW.audio_ready<>0 OR NEW.media_at IS NOT NULL OR (SELECT count(*) FROM live_guest_programme_connections WHERE output_id=NEW.output_id AND status IN('queued','connecting','connected'))>=3 THEN RAISE EXCEPTION 'Native programme connection requires independent current consent and capacity';END IF;
 ELSE
  IF (NEW.id,NEW.grant_id,NEW.peer_attempt_id,NEW.output_id,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.grant_id,OLD.peer_attempt_id,OLD.output_id,OLD.created_at) OR OLD.status IN('ended','failed','expired') OR NEW.version NOT BETWEEN OLD.version AND OLD.version+1 OR OLD.generation_id IS NOT NULL AND (NEW.generation_id,NEW.runtime_token) IS DISTINCT FROM (OLD.generation_id,OLD.runtime_token) THEN RAISE EXCEPTION 'Native programme connection identity and end are immutable';END IF;
  IF session_user<>worker_name AND (NEW.generation_id,NEW.runtime_token,NEW.server_offer,NEW.server_offer_hash,NEW.rtp_audio,NEW.rtp_video,NEW.decoded_frames,NEW.decoded_pcm_bytes,NEW.video_ready,NEW.audio_ready,NEW.media_at) IS DISTINCT FROM (OLD.generation_id,OLD.runtime_token,OLD.server_offer,OLD.server_offer_hash,OLD.rtp_audio,OLD.rtp_video,OLD.decoded_frames,OLD.decoded_pcm_bytes,OLD.video_ready,OLD.audio_ready,OLD.media_at) THEN RAISE EXCEPTION 'Native programme actual media receipts are worker-only';END IF;
  IF session_user<>worker_name AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN('ended','failed','expired') THEN RAISE EXCEPTION 'Native programme connection negotiation is worker-only';END IF;
  IF (NEW.mix_state,NEW.audio_muted,NEW.video_hidden) IS DISTINCT FROM (OLD.mix_state,OLD.audio_muted,OLD.video_hidden) AND NEW.version<>OLD.version+1 OR NEW.status IN('ended','failed','expired') AND NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Native programme controls require a new version';END IF;
  IF NEW.mix_state='on_air' AND OLD.mix_state<>'on_air' AND (NEW.status<>'connected' OR NOT dg_native_programme_live_valid(r.id) OR NEW.guest_lease_until::timestamptz<=clock_timestamp() OR r.camera=1 AND (NEW.video_ready<>1 OR NEW.decoded_frames<1) OR r.microphone=1 AND (NEW.audio_ready<>1 OR NEW.decoded_pcm_bytes<8000) OR NEW.media_at IS NULL OR NEW.media_at::timestamptz<clock_timestamp()-interval '2500 milliseconds') THEN RAISE EXCEPTION 'Native programme take requires actual current server media';END IF;
  IF NEW.guest_sequence<OLD.guest_sequence OR NEW.guest_lease_until<OLD.guest_lease_until OR NEW.guest_lease_until IS DISTINCT FROM OLD.guest_lease_until AND (NEW.guest_sequence<=OLD.guest_sequence OR OLD.guest_lease_until::timestamptz<=clock_timestamp() OR NOT dg_native_programme_live_valid(r.id)) THEN RAISE EXCEPTION 'Native programme stale heartbeat cannot renew media';END IF;
  IF OLD.guest_answer_hash IS NOT NULL AND (NEW.guest_answer_hash,NEW.guest_answer) IS DISTINCT FROM (OLD.guest_answer_hash,OLD.guest_answer) THEN RAISE EXCEPTION 'Native programme guest answer is fixed';END IF;
  IF NEW.status IN('ended','failed','expired') THEN NEW.mix_state:='off_air';NEW.server_offer:=NULL;NEW.server_offer_hash:=NULL;NEW.guest_answer:=NULL;NEW.guest_answer_hash:=NULL;NEW.video_ready:=0;NEW.audio_ready:=0;END IF;
 END IF;
 IF NEW.guest_lease_until::timestamptz>clock_timestamp()+interval '16 seconds' THEN RAISE EXCEPTION 'Native programme guest lease is bounded';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_programme_connection_guard BEFORE INSERT OR UPDATE ON live_guest_programme_connections FOR EACH ROW EXECUTE FUNCTION dg_native_programme_connection_guard();
CREATE FUNCTION dg_native_programme_connection_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF NEW.version>OLD.version THEN UPDATE live_sessions SET version=version+1,updated_at=dg_utc_now() WHERE id=(SELECT session_id FROM live_guest_programme_grants WHERE id=NEW.grant_id) AND status IN('live','preview');END IF;
 IF NEW.status IN('ended','failed','expired') THEN UPDATE live_guest_programme_controls SET status='superseded' WHERE connection_id=NEW.id AND status='pending';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_programme_connection_revision AFTER UPDATE ON live_guest_programme_connections FOR EACH ROW EXECUTE FUNCTION dg_native_programme_connection_revision();
CREATE FUNCTION dg_native_programme_control_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c live_guest_programme_connections%ROWTYPE;r live_guest_programme_grants%ROWTYPE;worker_name text;
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT c FROM live_guest_programme_connections WHERE id=NEW.connection_id;SELECT * INTO STRICT r FROM live_guest_programme_grants WHERE id=c.grant_id;
  IF NEW.output_id<>c.output_id OR NEW.version<>c.version OR NEW.session_version<>(SELECT version FROM live_sessions WHERE id=r.session_id) OR NEW.status<>'pending' OR NEW.applied_at IS NOT NULL OR NEW.media_frame IS NOT NULL OR NOT dg_native_peer_actor_valid(NEW.actor_id,r.tenant_id,r.workspace_id) THEN RAISE EXCEPTION 'Native programme control must match the current host and version';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','applied_at','media_frame']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','applied_at','media_frame']) OR OLD.status<>'pending' OR NEW.status NOT IN('applied','superseded') THEN RAISE EXCEPTION 'Native programme control receipt is immutable';END IF;
  SELECT worker_role INTO worker_name FROM _dg_native_runtime_control WHERE id=1;IF NEW.status='applied' AND session_user<>worker_name THEN RAISE EXCEPTION 'Native programme encoding acknowledgment is worker-only';END IF;
 END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_programme_control_guard BEFORE INSERT OR UPDATE ON live_guest_programme_controls FOR EACH ROW EXECUTE FUNCTION dg_native_programme_control_guard();
CREATE FUNCTION dg_native_programme_lifecycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_TABLE_NAME='live_guest_programme_grants' THEN
  IF NEW.status IN('withdrawn','expired','rejected') AND OLD.status IN('requested','consented') THEN UPDATE live_guest_programme_connections SET status='ended',mix_state='off_air',version=version+1,reason='节目及独立录制用途已撤回或到期',updated_at=dg_utc_now() WHERE grant_id=NEW.id AND status IN('queued','connecting','connected');END IF;
 ELSIF TG_TABLE_NAME='live_peer_attempts' THEN
  IF NEW.status<>'active' AND OLD.status='active' THEN UPDATE live_guest_programme_connections SET status='ended',mix_state='off_air',version=version+1,reason='后台设备已结束；独立录制用途仍按原期限管理',updated_at=dg_utc_now() WHERE peer_attempt_id=NEW.id AND status IN('queued','connecting','connected');END IF;
 ELSIF TG_TABLE_NAME='live_peer_invites' THEN
  IF NEW.status IN('revoked','expired','closed') AND OLD.status IN('issued','used') AND NOT(NEW.status='closed' AND EXISTS(SELECT 1 FROM live_sessions WHERE id=NEW.session_id AND status='ended')) THEN UPDATE live_guest_programme_grants SET status=CASE WHEN NEW.status='expired' THEN 'expired' ELSE 'withdrawn' END,version=version+1,updated_at=dg_utc_now() WHERE invite_id=NEW.id AND status IN('requested','consented');END IF;
 ELSIF TG_TABLE_NAME='live_outputs' THEN
  IF OLD.generation_id IS NOT NULL AND NEW.generation_id IS DISTINCT FROM OLD.generation_id THEN UPDATE live_guest_programme_connections SET status='ended',mix_state='off_air',version=version+1,reason='原节目代次已变化，需要新的主动节目授权',updated_at=dg_utc_now() WHERE output_id=NEW.id AND status IN('queued','connecting','connected');END IF;
 ELSE
  IF TG_OP='DELETE' OR (NEW.tenant_id,NEW.role,NEW.workspace_ids) IS DISTINCT FROM (OLD.tenant_id,OLD.role,OLD.workspace_ids) THEN UPDATE live_guest_programme_grants SET status='withdrawn',version=version+1,updated_at=dg_utc_now() WHERE actor_id=OLD.user_id AND status IN('requested','consented');END IF;
 END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_programme_grant_lifecycle AFTER UPDATE OF status ON live_guest_programme_grants FOR EACH ROW EXECUTE FUNCTION dg_native_programme_lifecycle();
CREATE TRIGGER native_programme_peer_lifecycle AFTER UPDATE OF status ON live_peer_attempts FOR EACH ROW EXECUTE FUNCTION dg_native_programme_lifecycle();
CREATE TRIGGER native_programme_invite_lifecycle AFTER UPDATE OF status ON live_peer_invites FOR EACH ROW EXECUTE FUNCTION dg_native_programme_lifecycle();
CREATE TRIGGER native_programme_generation_lifecycle AFTER UPDATE OF generation_id ON live_outputs FOR EACH ROW EXECUTE FUNCTION dg_native_programme_lifecycle();
CREATE TRIGGER native_programme_actor_lifecycle AFTER UPDATE OR DELETE ON memberships FOR EACH ROW EXECUTE FUNCTION dg_native_programme_lifecycle();

CREATE FUNCTION dg_native_programme_claim(p_connection text,p_output text,p_generation text,p_token text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c live_guest_programme_connections%ROWTYPE;
BEGIN
 IF NOT dg_native_programme_output_lease(p_output,p_generation,p_token) THEN RETURN false;END IF;SELECT * INTO c FROM live_guest_programme_connections WHERE id=p_connection AND output_id=p_output FOR UPDATE;IF NOT FOUND OR c.status NOT IN('queued','connecting','connected') THEN RETURN false;END IF;
 IF NOT dg_native_programme_live_valid(c.grant_id) OR c.guest_lease_until::timestamptz<=clock_timestamp() OR c.generation_id IS NOT NULL AND c.generation_id<>p_generation THEN UPDATE live_guest_programme_connections SET status='ended',mix_state='off_air',version=version+1,reason='原设备、心跳、授权或节目代次已失效，请重新确认',updated_at=dg_utc_now() WHERE id=c.id;RETURN false;END IF;
 IF c.generation_id IS NULL THEN UPDATE live_guest_programme_connections SET generation_id=p_generation,runtime_token=gen_random_uuid()::text,status='connecting',updated_at=dg_utc_now() WHERE id=c.id;END IF;RETURN true;
END $dg$;
CREATE FUNCTION dg_native_programme_message(p_output text,p_generation text,p_token text,p_message text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb;c live_guest_programme_connections%ROWTYPE;v jsonb;ra bigint;rv bigint;df bigint;dp bigint;description text;
BEGIN
 IF octet_length(p_message)>70000 OR NOT dg_native_programme_output_lease(p_output,p_generation,p_token) THEN RETURN false;END IF;j:=p_message::jsonb;SELECT * INTO c FROM live_guest_programme_connections WHERE id=j->>'id' AND output_id=p_output AND generation_id=p_generation AND runtime_token=j->>'runtimeToken' FOR UPDATE;IF NOT FOUND OR c.status NOT IN('queued','connecting','connected') THEN RETURN false;END IF;
 IF NOT dg_native_programme_live_valid(c.grant_id) OR c.guest_lease_until::timestamptz<=clock_timestamp() THEN UPDATE live_guest_programme_connections SET status='ended',mix_state='off_air',version=version+1,reason='原媒体授权或设备心跳已经结束',updated_at=dg_utc_now() WHERE id=c.id;RETURN false;END IF;
 IF j->>'type'='offer' THEN
  description:=j->'offer'->>'sdp';IF j->'offer'->>'type'<>'offer' OR description IS NULL OR octet_length(description) NOT BETWEEN 1 AND 65536 THEN RETURN false;END IF;
  IF c.server_offer_hash IS NOT NULL AND c.server_offer_hash<>encode(sha256(convert_to(description,'UTF8')),'hex') THEN RETURN false;END IF;
  IF c.server_offer IS NULL THEN UPDATE live_guest_programme_connections SET server_offer=description,server_offer_hash=encode(sha256(convert_to(description,'UTF8')),'hex'),updated_at=dg_utc_now() WHERE id=c.id;END IF;
 ELSIF j->>'type'='closed' THEN
  UPDATE live_guest_programme_connections SET status='failed',mix_state='off_air',version=version+1,reason='实际节目媒体连接已经关闭，请重新确认设备',updated_at=dg_utc_now() WHERE id=c.id;
 ELSIF j->>'type'='stats' THEN
  v:=j->'stats';IF NOT(v ?& ARRAY['rtpAudio','rtpVideo','decodedFrames','decodedPcmBytes','videoReady','audioReady','state']) OR v->>'state' NOT IN('new','connecting','connected','disconnected','failed','closed') THEN RETURN false;END IF;
  ra:=(v->>'rtpAudio')::bigint;rv:=(v->>'rtpVideo')::bigint;df:=(v->>'decodedFrames')::bigint;dp:=(v->>'decodedPcmBytes')::bigint;
  IF ra NOT BETWEEN c.rtp_audio AND 1000000000000 OR rv NOT BETWEEN c.rtp_video AND 1000000000000 OR df NOT BETWEEN c.decoded_frames AND 1000000000000 OR dp NOT BETWEEN c.decoded_pcm_bytes AND 1000000000000 OR (v->>'videoReady')::boolean AND df<1 OR (v->>'audioReady')::boolean AND dp<8000 THEN RETURN false;END IF;
  UPDATE live_guest_programme_connections SET status=CASE WHEN v->>'state'='connected' THEN 'connected' ELSE 'connecting' END,rtp_audio=ra,rtp_video=rv,decoded_frames=df,decoded_pcm_bytes=dp,video_ready=CASE WHEN (v->>'videoReady')::boolean THEN 1 ELSE 0 END,audio_ready=CASE WHEN (v->>'audioReady')::boolean THEN 1 ELSE 0 END,media_at=dg_utc_now(),updated_at=dg_utc_now() WHERE id=c.id;
 ELSE RETURN false;END IF;RETURN true;
END $dg$;
CREATE FUNCTION dg_native_programme_instruction(p_connection text,p_output text,p_generation text,p_token text,p_payload text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c live_guest_programme_connections%ROWTYPE;r live_guest_programme_grants%ROWTYPE;expected jsonb;old_hash text;h text;
BEGIN
 IF NOT dg_native_programme_output_lease(p_output,p_generation,p_token) THEN RETURN false;END IF;SELECT * INTO c FROM live_guest_programme_connections WHERE id=p_connection AND output_id=p_output AND generation_id=p_generation;IF NOT FOUND OR c.status<>'connected' OR c.mix_state<>'on_air' OR NOT dg_native_programme_live_valid(c.grant_id) OR c.guest_lease_until::timestamptz<=clock_timestamp() THEN RETURN false;END IF;SELECT * INTO STRICT r FROM live_guest_programme_grants WHERE id=c.grant_id;
 expected:=jsonb_build_object('connectionId',c.id,'grantId',r.id,'consentHash',r.consent_hash,'controlVersion',c.version,'publicName',r.public_name,'camera',r.camera=1,'microphone',r.microphone=1,'recordingAllowed',r.recording_allowed=1,'expiresAt',r.expires_at,'audioMuted',c.audio_muted=1,'videoHidden',c.video_hidden=1);
 IF p_payload::jsonb IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Native programme frame instruction differs from the selected consent';END IF;h:=encode(sha256(convert_to(p_payload,'UTF8')),'hex');SELECT payload_hash INTO old_hash FROM _dg_native_programme_instructions WHERE connection_id=c.id AND version=c.version;IF old_hash IS NOT NULL THEN IF old_hash<>h THEN RAISE EXCEPTION 'Native programme selected frame instruction cannot change';END IF;RETURN true;END IF;
 INSERT INTO _dg_native_programme_instructions VALUES(c.id,c.version,p_generation,c.runtime_token,p_payload,h,dg_utc_now());RETURN true;
END $dg$;
CREATE FUNCTION dg_native_programme_ack(p_output text,p_generation text,p_token text,p_cutoff bigint) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_guest_programme_controls%ROWTYPE;c live_guest_programme_connections%ROWTYPE;applied bigint;n integer:=0;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM live_guest_programme_controls WHERE output_id=p_output AND status='pending') THEN RETURN 0;END IF;IF NOT dg_native_programme_output_lease(p_output,p_generation,p_token) OR NOT EXISTS(SELECT 1 FROM live_output_generations WHERE id=p_generation AND p_cutoff<=start_frame+encoded_frames) THEN RETURN 0;END IF;
 FOR r IN SELECT * FROM live_guest_programme_controls WHERE output_id=p_output AND status='pending' ORDER BY requested_at,id FOR UPDATE LOOP
  SELECT * INTO STRICT c FROM live_guest_programme_connections WHERE id=r.connection_id;IF c.version<>r.version THEN UPDATE live_guest_programme_controls SET status='superseded' WHERE id=r.id;CONTINUE;END IF;
  SELECT s.first_frame INTO applied FROM live_output_spans s WHERE s.generation_id=p_generation AND s.first_frame<p_cutoff AND s.session_version>=r.session_version AND
   CASE WHEN c.mix_state<>'on_air' OR r.action IN('preview','end') THEN NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(s.frame::jsonb->'guests','[]'::jsonb)) v WHERE v->>'connectionId'=c.id)
   ELSE EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(s.frame::jsonb->'guests','[]'::jsonb)) v WHERE v->>'connectionId'=c.id AND (v->>'controlVersion')::bigint=r.version AND (v->>'audioMuted')::boolean=(c.audio_muted=1) AND (v->>'videoHidden')::boolean=(c.video_hidden=1)) END ORDER BY s.first_frame LIMIT 1;
  IF applied IS NOT NULL THEN UPDATE live_guest_programme_controls SET status='applied',applied_at=dg_utc_now(),media_frame=applied WHERE id=r.id;n:=n+1;END IF;
 END LOOP;RETURN n;
END $dg$;
CREATE FUNCTION dg_native_programme_sweep() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_guest_programme_grants%ROWTYPE;c live_guest_programme_connections%ROWTYPE;n integer:=0;
BEGIN
 FOR r IN SELECT * FROM live_guest_programme_grants WHERE status IN('requested','consented') AND expires_at::timestamptz<=clock_timestamp() ORDER BY id LIMIT 500 FOR UPDATE SKIP LOCKED LOOP UPDATE live_guest_programme_grants SET status='expired',version=version+1,updated_at=dg_utc_now() WHERE id=r.id;n:=n+1;END LOOP;
 FOR r IN SELECT g.* FROM live_guest_programme_grants g JOIN live_peer_attempts a ON a.id=g.peer_attempt_id JOIN live_peer_invites i ON i.id=g.invite_id WHERE g.status='requested' AND (a.status<>'active' OR i.status<>'used' OR a.host_lease_until::timestamptz<=clock_timestamp() OR a.guest_lease_until::timestamptz<=clock_timestamp()) ORDER BY g.id LIMIT 500 FOR UPDATE OF g SKIP LOCKED LOOP UPDATE live_guest_programme_grants SET status='rejected',version=version+1,updated_at=dg_utc_now() WHERE id=r.id;n:=n+1;END LOOP;
 FOR c IN SELECT * FROM live_guest_programme_connections WHERE status IN('queued','connecting','connected') AND (guest_lease_until::timestamptz<=clock_timestamp() OR status='connected' AND (media_at IS NULL OR media_at::timestamptz<clock_timestamp()-interval '5 seconds') OR status<>'connected' AND created_at::timestamptz<clock_timestamp()-interval '30 seconds' OR NOT dg_native_programme_live_valid(grant_id)) ORDER BY id LIMIT 500 FOR UPDATE SKIP LOCKED LOOP UPDATE live_guest_programme_connections SET status='expired',mix_state='off_air',version=version+1,reason='设备、媒体心跳或当前节目来源已结束，请重新确认',updated_at=dg_utc_now() WHERE id=c.id;n:=n+1;END LOOP;RETURN n;
END $dg$;
REVOKE ALL ON FUNCTION dg_native_programme_append_only(),dg_native_programme_payload(live_guest_programme_grants),dg_native_programme_source_valid(text,text,text,text,boolean),dg_native_programme_live_valid(text),dg_native_programme_output_lease(text,text,text),dg_native_programme_grant_guard(),dg_native_programme_pair_guard(),dg_native_programme_connection_guard(),dg_native_programme_connection_revision(),dg_native_programme_control_guard(),dg_native_programme_lifecycle(),dg_native_programme_claim(text,text,text,text),dg_native_programme_message(text,text,text,text),dg_native_programme_instruction(text,text,text,text,text),dg_native_programme_ack(text,text,text,bigint),dg_native_programme_sweep() FROM PUBLIC;
